// scripts/blast-radius.ts
import { buildReport, loadSharedLoomConfig, mergeLoomSettings, readManifestLoomSection, validateLoomSection } from '@pyreon/loom/core'

// the settings `loom scan` applies: pyreon.config.* merged with the package.json `loom` key
const shared = await loadSharedLoomConfig('.')
const manifest = validateLoomSection(readManifestLoomSection('.'), 'package.json')
const report = buildReport('.', { settings: mergeLoomSettings(shared, manifest) })

// The ten packages whose change reaches the most of the workspace.
const top = Object.entries(report.graph.reach)
  .sort(([, a], [, b]) => b - a)
  .slice(0, 10)
for (const [pkg, dependents] of top) console.log(`${dependents}\t${pkg}`)

const errors = report.issues.filter((i) => i.severity === 'error')
if (errors.length > 0) process.exitCode = 1

// package.json (root)
{
  "workspaces": ["packages/*"],
  "loom": {
    "devPaths": ["src/manifest.ts", "**/*.gen.ts"],
    "severity": { "prod-import-of-dev-dep": "error" },
    "ignore": [
      {
        "pkg": "@acme/app",
        "dep": "nanoid",
        "code": "phantom-dep",
        "reason": "provided by the host app at runtime"
      }
    ]
  }
}
